  ?item wdt:P31/wdt:P279* wd:Q11424;
        wdt:P577 ?date;
        wdt:P57 ?answer.

  FILTER(?date >= "2026-01-01T00:00:00Z"^^xsd:dateTime)
  FILTER(?date <= "2026-05-06T23:59:59Z"^^xsd:dateTime)

  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "en".
